package com.aicommerce.platform.delivery.application.port;
import java.time.Instant; import java.util.*; import com.aicommerce.platform.delivery.domain.*;
public record PlatformCampaignCommand(PlatformCommandIdentity identity,UUID platformCampaignUuid,UUID campaignUuid,PlatformObjective objective,PlatformDesiredState desiredState,Optional<Instant> scheduleStart,Optional<Instant> scheduleEnd,String accountTimezone){public PlatformCampaignCommand{PlatformContractSupport.req(identity);PlatformContractSupport.req(platformCampaignUuid);PlatformContractSupport.req(campaignUuid);PlatformContractSupport.req(objective);PlatformContractSupport.req(desiredState);scheduleStart=PlatformContractSupport.opt(scheduleStart);scheduleEnd=PlatformContractSupport.opt(scheduleEnd);if(desiredState!=PlatformDesiredState.PAUSED||scheduleStart.isPresent()!=scheduleEnd.isPresent()||(scheduleStart.isPresent()&&!scheduleEnd.get().isAfter(scheduleStart.get()))||!"Asia/Taipei".equals(accountTimezone))throw PlatformContractSupport.invalid();}}
